-- Frozen differential fixtures generated from real NumPy 2.3.5
local np=require("luaray_core")
assert(np._version=="0.99.1-dev")
local checks,cases=0,0
local function deep(a,b,desc)
    assert(type(a)==type(b),desc..': type mismatch: '..type(a)..' vs '..type(b))
    if type(a)=='table' then
        assert(#a==#b,desc..': length mismatch: '..#a..' vs '..#b)
        for i=1,#a do deep(a[i],b[i],desc..'['..i..']') end
    else
        assert(a==b,desc..': '..tostring(a)..' vs '..tostring(b))
    end
    checks=checks+1
end
do
local r=np.random.default_rng(4294967297)
local x=np.transpose(np.astype(np.arange(12,"int64"):reshape({3,4}),"int32"),{2,1})
local before=x:tolist()
local y=r:permuted(x,nil)
deep(y.dtype,"int32","4294967297/(3, 4)/int32/transpose/None/copy dtype")
deep(y:tolist(),{{6,7,5},{2,1,11},{4,0,8},{9,3,10}},"4294967297/(3, 4)/int32/transpose/None/copy values")
deep(x:tolist(),{{0,4,8},{1,5,9},{2,6,10},{3,7,11}},"4294967297/(3, 4)/int32/transpose/None/copy source")
deep(r:raw_hex(),"f3fe33f26b689233","4294967297/(3, 4)/int32/transpose/None/copy pcg")
cases=cases+1; end
